const [latestR, opR] = await Promise.all([
  tools.fetchSite('https://data.priceai.cc/latest.json', { asSite: false, credentials: 'omit', timeout: 15000 }),
  tools.fetchSite('https://priceai.cc/official-prices', { asSite: true, credentials: 'include', timeout: 20000 }),
]);
const meta = latestR?.json || {};
const html = opR?.text || '';
const parts = [];
const re = /self\.__next_f\.push\(\[1,"((?:[^"\\]|\\.)*)"\]\)/g;
let m;
while ((m = re.exec(html)) !== null) {
  try { parts.push(JSON.parse('"' + m[1] + '"')); } catch {}
}
const joined = parts.join('');
let plans = [];
const needle = '"planSummaries":';
const idx = joined.indexOf(needle);
if (idx >= 0) {
  const i = idx + needle.length;
  if (joined[i] === '[') {
    let depth = 0, inStr = false, esc = false;
    for (let j = i; j < joined.length; j++) {
      const ch = joined[j];
      if (inStr) { if (esc) esc = false; else if (ch === '\\') esc = true; else if (ch === '"') inStr = false; }
      else {
        if (ch === '"') inStr = true;
        else if (ch === '[') depth++;
        else if (ch === ']') {
          if (--depth === 0) {
            try { plans = JSON.parse(joined.slice(i, j + 1)); } catch {}
            break;
          }
        }
      }
    }
  }
}
const cleanStr = s => (typeof s === 'string' && s.startsWith('$$')) ? s.slice(1) : (s === '$undefined' ? null : s);
return {
  site: 'PriceAI (https://priceai.cc)',
  snapshot: {
    id: meta.snapshot_id,
    generatedAt: meta.generated_at,
    stale: meta.stale,
    standardProducts: meta.product_count,
  },
  officialSubscriptions: plans.map(x => ({
    id: x.id,
    platform: x.platform,
    label: x.label,
    usUsd: x.usRow?.usdPrice ?? null,
    usCny: x.usRow?.cnyPrice ?? null,
    lowestCountry: x.lowestRow?.countryLabel ?? null,
    lowestChannel: x.lowestRow?.channelSlug ?? null,
    lowestText: cleanStr(x.lowestRow?.priceText),
    lowestCny: x.lowestRow?.cnyPrice ?? null,
    lowestUsd: x.lowestRow?.usdPrice ?? null,
  })),
  tip: '用 plugin.web.act {id:"priceai", action:"official_plans|official_regions|products|product_detail|radar|offers|merchants|api_plans|transit|guides"} 查各模块明细',
};

actionCode:
const ORIGIN = 'https://priceai.cc';
const p = (args && typeof args.args === 'object' && args.args) ? args.args : (args || {});
const act = String(kind || args?.action || 'official_plans').trim().toLowerCase();

const cleanRsc = (v) => {
  if (v === '$undefined') return null;
  if (typeof v === 'string') {
    if (v.startsWith('$$')) return v.slice(1);
    if (/^\$[0-9a-z]+:/.test(v)) return null;
    return v;
  }
  if (Array.isArray(v)) return v.map(cleanRsc);
  if (v && typeof v === 'object') {
    const o = {};
    for (const k of Object.keys(v)) o[k] = cleanRsc(v[k]);
    return o;
  }
  return v;
};

const getRscJoined = (html) => {
  if (!html) return '';
  const parts = [];
  const re = /self\.__next_f\.push\(\[1,"((?:[^"\\]|\\.)*)"\]\)/g;
  let m;
  while ((m = re.exec(html)) !== null) {
    try { parts.push(JSON.parse('"' + m[1] + '"')); } catch { parts.push(m[1]); }
  }
  return parts.join('');
};

const extractRscKey = (joined, key) => {
  const needle = `"${key}":`;
  let pos = 0;
  while (true) {
    const idx = joined.indexOf(needle, pos);
    if (idx < 0) return null;
    const i = idx + needle.length;
    const open = joined[i];
    const close = open === '[' ? ']' : open === '{' ? '}' : null;
    if (!close) { pos = i; continue; }
    let depth = 0, inStr = false, esc = false;
    for (let j = i; j < joined.length; j++) {
      const ch = joined[j];
      if (inStr) {
        if (esc) esc = false;
        else if (ch === '\\') esc = true;
        else if (ch === '"') inStr = false;
      } else {
        if (ch === '"') inStr = true;
        else if (ch === open) depth++;
        else if (ch === close) {
          depth--;
          if (depth === 0) {
            try { return cleanRsc(JSON.parse(joined.slice(i, j + 1))); }
            catch { pos = j + 1; break; }
          }
        }
      }
    }
    if (depth !== 0) return null;
  }
};

const decodeHtml = (s) => String(s || '')
  .replace(/&nbsp;/gi, ' ')
  .replace(/&amp;/gi, '&')
  .replace(/&lt;/gi, '<')
  .replace(/&gt;/gi, '>')
  .replace(/&quot;/gi, '"')
  .replace(/&#39;|&#x27;/gi, "'")
  .replace(/&#(\d+);/g, (_, n) => String.fromCharCode(Number(n)))
  .replace(/&#x([0-9a-f]+);/gi, (_, h) => String.fromCharCode(parseInt(h, 16)));

const stripTags = (s) => decodeHtml(String(s || '').replace(/<[^>]+>/g, ' ')).replace(/\s+/g, ' ').trim();

const fetchSite = async (url, asSite = true) => {
  const full = /^https?:\/\//i.test(url) ? url : ORIGIN + url;
  const r = await tools.fetchSite(full, { asSite, credentials: asSite ? 'include' : 'omit', timeout: 25000 });
  if (!r || r.status >= 400) throw new Error(`请求失败 HTTP ${r?.status || '?'} (${full})`);
  return r;
};

const norm = (s) => String(s || '').toLowerCase().trim();
const matchQ = (q, ...fields) => {
  if (!q) return true;
  const tokens = norm(q).split(/\s+/).filter(Boolean);
  const hay = fields.map(f => Array.isArray(f) ? f.join(' ') : String(f || '')).join(' ').toLowerCase();
  return tokens.every(t => hay.includes(t));
};

const parseTagList = (v) => {
  if (!v) return [];
  const arr = Array.isArray(v) ? v : String(v).split(/[,，\s]+/);
  return [...new Set(arr.map(x => String(x || '').trim()).filter(Boolean))];
};

const parseNumOpt = (v) => {
  if (v == null || v === '') return null;
  const n = Number(v);
  return Number.isFinite(n) && n >= 0 ? n : null;
};

// 严格真有货判定：修复部分 out_of_stock 报价 effectiveStatus 仍为 available、或 in_stock 但 effectiveStatus=unavailable 的边界
const isTrulyAvailable = (o) => !!o
  && (o.status === 'in_stock' || o.status === 'low_stock')
  && (o.effectiveStatus == null || o.effectiveStatus === 'available')
  && (o.stockCount == null || Number(o.stockCount) > 0);

const offerMatchesClientTag = (o, tag) => {
  const tg = norm(tag);
  if (!tg) return true;
  return (o.filterTags || []).some(t => norm(t) === tg || norm(t).includes(tg))
    || (o.tags || []).some(t => norm(t).includes(tg))
    || norm(o.sourceTitle).includes(tg);
};

const fmtOfficialRow = (r) => r ? ({
  country: r.countryLabel || r.countryCode,
  countryCode: r.countryCode,
  channel: r.channelSlug,
  currency: r.currencyCode,
  priceText: r.priceText,
  priceValue: r.priceValue,
  cnyPrice: r.cnyPrice,
  usdPrice: r.usdPrice,
  taxTreatment: r.taxTreatment,
  priceKind: r.priceKind,
  fxDate: r.fxDate,
  sourceUrl: r.sourceUrl,
  fetchedAt: r.fetchedAt,
}) : null;

const VALID_OFFER_SORTS = new Set(['available_price', 'price', 'updated', 'channels']);

// 单商品多维实时报价查询：走服务端 /api/products/{slug}/offers + 严守 limit<=30 & offset<=300 + 自动补滤与安全翻页
const queryProductOffers = async (slug, opt = {}) => {
  const cleanSlug = String(slug || '').trim().replace(/^\/+products\//, '');
  if (!cleanSlug) throw new Error('请提供商品 slug，例如 chatgpt-plus、claude-max-20x、gemini-pro-year、super-grok');

  const reqTags = parseTagList(opt.tags ?? opt.tag);
  const qStr = opt.q ? String(opt.q).trim() : '';
  const excludeStr = opt.exclude ? String(opt.exclude).trim() : '';
  const minVal = parseNumOpt(opt.min ?? opt.minPrice);
  const maxVal = parseNumOpt(opt.max ?? opt.maxPrice);
  const collector = opt.collector && opt.collector !== 'all' ? String(opt.collector).trim() : '';
  const minStock = parseNumOpt(opt.minStock);
  const freshWithin = parseNumOpt(opt.freshWithin);
  const stockMode = norm(opt.stock);
  const onlyAvailable = stockMode === 'all' ? false : (stockMode === 'out_of_stock' ? false : opt.onlyAvailable !== false);
  const want = Math.max(1, Math.min(30, Number(opt.limit) || 20));
  const startOffset = Math.max(0, Math.min(300, Number(opt.offset) || 0));
  const maxPages = Math.max(1, Math.min(5, Number(opt.maxPages) || 4));
  const sortMode = norm(opt.sort);

  const buildQs = (pageLimit, pageOffset) => {
    const qs = new URLSearchParams();
    if (reqTags.length) qs.set('tags', reqTags.join(','));
    if (qStr) qs.set('q', qStr);
    if (excludeStr) qs.set('exclude', excludeStr);
    if (collector) qs.set('collector', collector);
    if (minVal != null) qs.set('min', String(minVal));
    if (maxVal != null) qs.set('max', String(maxVal));
    // 服务端仅认 minStock=50 与 freshWithin=60，满足条件时顺便传给服务端加速
    if (minStock != null && minStock >= 50) qs.set('minStock', '50');
    if (freshWithin != null && freshWithin <= 60) qs.set('freshWithin', '60');
    qs.set('limit', String(Math.max(1, Math.min(30, pageLimit))));
    qs.set('offset', String(Math.max(0, Math.min(300, pageOffset))));
    return qs.toString();
  };

  const needsClientFilter = onlyAvailable || stockMode === 'out_of_stock' || minStock != null || freshWithin != null || reqTags.length > 0;
  const pageLimit = (needsClientFilter || sortMode === 'price') ? 30 : want;

  let firstData = null;
  let serverActiveTags = [];
  let clientFilterTags = [];
  let total = 0;
  let generatedAt = null;
  let filterFacets = [];
  let offset = startOffset;
  let pagesFetched = 0;
  const seenIds = new Set();
  const matched = [];
  const observedCounts = new Map();
  const nowMs = Date.now();

  try {
    while (pagesFetched < maxPages && offset <= 300) {
      const r = await fetchSite(`/api/products/${encodeURIComponent(cleanSlug)}/offers?${buildQs(pageLimit, offset)}`);
      const data = r.json || {};
      const pageOffers = Array.isArray(data.offers) ? data.offers : [];
      pagesFetched++;
      if (!firstData) {
        firstData = data;
        total = Number(data.total) || pageOffers.length;
        generatedAt = data.generatedAt || null;
        filterFacets = Array.isArray(data.filterFacets) ? data.filterFacets : [];
        serverActiveTags = Array.isArray(data.activeFilterTags) ? data.activeFilterTags : [];
        clientFilterTags = reqTags.filter(t => !serverActiveTags.includes(t));
      }

      for (const o of pageOffers) {
        for (const t of (o.filterTags || [])) observedCounts.set(t, (observedCounts.get(t) || 0) + 1);
        if (o.id && seenIds.has(o.id)) continue;
        if (stockMode === 'out_of_stock') {
          if (isTrulyAvailable(o)) continue;
        } else if (onlyAvailable && !isTrulyAvailable(o)) {
          continue;
        }
        if (clientFilterTags.length && !clientFilterTags.every(tg => offerMatchesClientTag(o, tg))) continue;
        if (minStock != null && (o.stockCount == null || Number(o.stockCount) < minStock)) continue;
        if (freshWithin != null) {
          const ts = Date.parse(o.verifiedAt || o.lastSeenAt || o.capturedAt || o.sourceUpdatedAt || '');
          if (!Number.isFinite(ts) || ts < nowMs - freshWithin * 60000) continue;
        }
        if (o.id) seenIds.add(o.id);
        matched.push(o);
      }

      offset += pageOffers.length;
      if (pageOffers.length < pageLimit || offset >= total || offset > 300) break;
      if (matched.length >= want && sortMode !== 'price') break;
      if (matched.length >= Math.max(want * 2, 30)) break;
    }
  } catch (err) {
    if (!firstData) {
      // 平滑回退至 Price Radar 公开静态快照
      const latest = await fetchSite('https://data.priceai.cc/latest.json', false);
      const snap = await fetchSite(latest.json.snapshot_url, false);
      const hit = (snap.json?.products || []).find(x => x.slug === cleanSlug || x.id === cleanSlug);
      if (!hit) throw err;
      return { source: 'radar_snapshot', product: hit };
    }
  }

  if (sortMode === 'price') {
    matched.sort((a, b) => (Number(a.price) || 1e9) - (Number(b.price) || 1e9));
  }

  const finalOffers = matched.slice(0, want);
  const observedFilterTags = [...observedCounts.entries()]
    .sort((a, b) => b[1] - a[1])
    .slice(0, 20)
    .map(([id, count]) => ({ id, count }));

  return {
    slug: cleanSlug,
    url: `${ORIGIN}/products/${cleanSlug}`,
    generatedAt,
    total,
    pagesFetched,
    hasMore: offset < total && offset <= 300,
    activeFilterTags: serverActiveTags,
    clientFilterTags,
    filterFacets: filterFacets.map(f => ({ id: f.id, label: f.label, group: f.group, count: f.count, description: f.description })),
    observedFilterTags,
    returned: finalOffers.length,
    offers: finalOffers.map(o => ({
      id: o.id,
      title: o.sourceTitle,
      price: o.price,
      currency: o.currency,
      status: o.status,
      effectiveStatus: o.effectiveStatus,
      freshnessStatus: o.freshnessStatus || null,
      inStock: isTrulyAvailable(o),
      stockCount: o.stockCount,
      minOrderQuantity: o.minOrderQuantity,
      bulkPricingTiers: o.bulkPricingTiers,
      store: o.sourceStoreName || o.sourceName,
      collector: o.collectorKind || null,
      salesText: o.platformSalesText || null,
      filterTags: o.filterTags || [],
      url: o.url,
      shopUrl: o.shopUrl,
      lastSeenAt: o.lastSeenAt,
    })),
  };
};

// 1. 官方订阅概览与跨区最低价对比
if (act === 'official_plans' || act === 'observe') {
  const r = await fetchSite('/official-prices');
  const rsc = getRscJoined(r.text);
  const apps = extractRscKey(rsc, 'apps') || [];
  const channels = extractRscKey(rsc, 'channels') || [];
  const rawPlans = extractRscKey(rsc, 'planSummaries') || [];
  const pf = norm(p.platform);
  const q = p.q || '';
  const plans = rawPlans
    .filter(x => (!pf || norm(x.appSlug) === pf || norm(x.platform) === pf) && matchQ(q, x.label, x.platform, x.provider, x.planSlug, x.id))
    .map(x => {
      const chs = {};
      for (const ck of ['web_direct', 'app_store', 'google_play']) {
        const c = x.channels?.[ck];
        if (!c) continue;
        const lr = c.lowestRow || (x.lowestRow?.channelSlug === ck ? x.lowestRow : null);
        chs[ck] = { sampleCount: c.sampleCount, lowest: fmtOfficialRow(lr) };
      }
      const usCny = x.usRow?.cnyPrice;
      const loCny = x.lowestRow?.cnyPrice;
      const savingsPct = (usCny > 0 && loCny > 0) ? Math.round((1 - loCny / usCny) * 1000) / 10 : null;
      return {
        id: x.id,
        platform: x.platform,
        appSlug: x.appSlug,
        planSlug: x.planSlug,
        provider: x.provider,
        label: x.label,
        billingPeriod: x.billingPeriod,
        sampleCount: x.sampleCount,
        usPrice: fmtOfficialRow(x.usRow),
        lowestPrice: fmtOfficialRow(x.lowestRow),
        savingsPct,
        channels: chs,
        updatedAt: x.latestFetchedAt,
        url: `${ORIGIN}/official-prices/${x.id}`,
        markdownUrl: `${ORIGIN}/official-prices/md/${x.id}`,
      };
    });
  return {
    source: `${ORIGIN}/official-prices`,
    appCount: apps.length,
    apps: apps.map(a => ({ slug: a.slug, name: a.displayName, provider: a.provider })),
    channels: channels.map(c => ({ slug: c.slug, label: c.label, priceKind: c.priceKind, exactOfferCount: c.exactOfferCount, updatedAt: c.priceUpdatedAt })),
    planCount: plans.length,
    plans,
  };
}

// 2. 官方订阅全球地区价明细（支持 format:"markdown" 直接拉取 /official-prices/md/{id} 完整地区表）
if (act === 'official_regions') {
  if (norm(p.format) === 'markdown' && (p.id || p.plan)) {
    const rawId = String(p.id || p.plan).trim();
    const mdId = rawId.includes('__') ? rawId : (p.platform ? `${norm(p.platform)}__${rawId}` : rawId);
    const r = await fetchSite(`/official-prices/md/${encodeURIComponent(mdId)}`);
    const content = String(r.text || '').trim();
    return {
      id: mdId,
      url: `${ORIGIN}/official-prices/${mdId}`,
      markdownUrl: `${ORIGIN}/official-prices/md/${mdId}`,
      length: content.length,
      content: content.slice(0, Number(p.maxChars) || 15000),
    };
  }
  const qs = new URLSearchParams();
  if (p.platform) qs.set('platform', String(p.platform).toLowerCase());
  if (p.channel) qs.set('channel', String(p.channel));
  const planKw = p.plan ? String(p.plan).replace(/^[a-z0-9]+__/i, '').replace(/-(monthly|annual)$/i, '').replace(/[-_]+/g, ' ').trim() : '';
  const serverQ = p.q ? String(p.q) : planKw;
  if (serverQ) qs.set('q', serverQ);
  if (p.scope) qs.set('scope', String(p.scope));
  if (p.currency) qs.set('currency', String(p.currency));
  qs.set('page', String(Math.max(1, Number(p.page) || 1)));
  const r = await fetchSite(`/api/official-prices/offers?${qs.toString()}`);
  const data = r.json || {};
  let rows = Array.isArray(data.rows) ? data.rows : [];
  if (p.plan) {
    const pl = norm(p.plan);
    const exact = rows.filter(x => norm(x.planSlug).includes(pl) || norm(x.planLabel).includes(pl) || norm(x.id).includes(pl) || (planKw && norm(x.planLabel).includes(norm(planKw))));
    if (exact.length) rows = exact;
  }
  const lim = Math.max(1, Math.min(100, Number(p.limit) || 30));
  return {
    total: data.total || rows.length,
    page: data.page || 1,
    pageCount: data.pageCount || 1,
    count: Math.min(rows.length, lim),
    rows: rows.slice(0, lim).map(x => ({
      id: x.id,
      platform: x.app?.displayName || x.appSlug,
      appSlug: x.appSlug,
      planSlug: x.planSlug,
      planLabel: x.planLabel,
      billingPeriod: x.plan?.billingPeriod,
      channel: x.channelSlug,
      country: x.countryLabel,
      countryCode: x.countryCode,
      currency: x.currencyCode,
      priceText: x.priceText,
      priceValue: x.priceValue,
      cnyPrice: x.cnyPrice,
      usdPrice: x.usdPrice,
      taxTreatment: x.taxTreatment,
      priceKind: x.priceKind,
      fxDate: x.fxDate,
      sourceUrl: x.sourceUrl,
      fetchedAt: x.fetchedAt,
    })),
  };
}

// 3. 卡网/全站标准商品目录
if (act === 'products') {
  const scope = p.scope === 'third_party' ? 'third_party' : 'all';
  const r = await fetchSite(scope === 'third_party' ? '/api/explorer/channels' : '/api/explorer');
  const data = r.json || {};
  let list = Array.isArray(data.products) ? data.products : [];
  const pf = norm(p.platform);
  const tp = norm(p.type);
  const q = p.q || '';
  list = list.filter(x => {
    if (pf && norm(x.platform) !== pf && !norm(x.platform).includes(pf)) return false;
    if (tp && norm(x.productType) !== tp && !norm(x.productType).includes(tp)) return false;
    if (p.onlyInStock && !(x.inStockCount > 0)) return false;
    return matchQ(q, x.displayName, x.slug, x.platform, x.productType, x.spec, x.summary, x.aliases);
  });
  if (p.sort === 'price') list.sort((a, b) => (a.lowestPrice ?? 1e9) - (b.lowestPrice ?? 1e9));
  else if (p.sort === 'offers') list.sort((a, b) => (b.inStockCount ?? 0) - (a.inStockCount ?? 0));
  const lim = p.limit === 0 ? list.length : Math.max(1, Math.min(200, Number(p.limit) || 30));
  return {
    scope: data.scope || scope,
    generatedAt: data.generatedAt,
    offerTotal: data.offerTotal,
    matched: list.length,
    products: list.slice(0, lim).map(x => ({
      slug: x.slug,
      name: x.displayName,
      platform: x.platform,
      productType: x.productType,
      spec: x.spec,
      summary: x.summary,
      lowestPrice: x.lowestPrice,
      currency: x.lowestOffer?.currency || 'CNY',
      lowestLabel: x.lowestPriceLabel,
      lowestStore: x.lowestOffer?.sourceStoreName || x.lowestOffer?.sourceName || null,
      lowestTitle: x.lowestOffer?.sourceTitle || null,
      warrantyLowestPrice: x.warrantyLowestPrice ?? null,
      warrantyOfferCount: x.warrantyOfferCount ?? 0,
      offerCount: x.offerCount,
      inStockCount: x.inStockCount,
      outOfStockCount: x.outOfStockCount,
      latestSeenAt: x.latestSeenAt,
      url: `${ORIGIN}/products/${x.slug}`,
    })),
  };
}

// 4. 单个标准商品详情与多维服务端筛选报价（/api/products/{slug}/offers）
if (act === 'product_detail') {
  return await queryProductOffers(p.slug || p.product, p);
}

// 5. PriceAI 官方公开快照 Feed (data.priceai.cc，零风控)
if (act === 'radar') {
  const latest = await fetchSite('https://data.priceai.cc/latest.json', false);
  const meta = latest.json || {};
  if (!meta.snapshot_url) throw new Error('未获取到 snapshot_url');
  const snap = await fetchSite(meta.snapshot_url, false);
  const prods = snap.json?.products || [];
  if (p.slug) {
    const sl = norm(p.slug);
    const hit = prods.find(x => norm(x.slug) === sl || norm(x.id) === sl) || prods.find(x => norm(x.slug).includes(sl) || norm(x.name).includes(sl));
    if (!hit) throw new Error(`快照中未找到商品: ${p.slug}`);
    return { snapshotId: meta.snapshot_id, generatedAt: meta.generated_at, stale: meta.stale, product: hit };
  }
  const pf = norm(p.platform);
  const q = p.q || '';
  const filtered = prods.filter(x => (!pf || norm(x.platform) === pf || norm(x.platform).includes(pf)) && matchQ(q, x.name, x.slug, x.platform, x.spec, x.summary));
  const lim = Math.max(1, Math.min(100, Number(p.limit) || 25));
  return {
    snapshotId: meta.snapshot_id,
    generatedAt: meta.generated_at,
    publishedAt: meta.published_at,
    stale: meta.stale,
    totalProducts: prods.length,
    matched: filtered.length,
    products: filtered.slice(0, lim).map(x => ({
      slug: x.slug,
      name: x.name,
      platform: x.platform,
      productType: x.product_type,
      spec: x.spec,
      summary: x.summary,
      lowestPrice: x.lowest_price,
      inStockCount: x.in_stock_count,
      offerCount: x.offer_count,
      presetIds: (x.presets || []).map(pr => pr.id),
      topOffers: (x.top_offers || []).slice(0, 3).map(o => ({
        title: o.title, price: o.price, currency: o.currency, store: o.source_store_name || o.source_name,
        stockCount: o.stock_count, url: o.url, lastSeenAt: o.last_seen_at,
      })),
    })),
  };
}

// 6. 全站卡网实时报价搜索（严守 limit<=30, offset<=300；传 product/slug 自动路由至 /api/products/{slug}/offers）
if (act === 'offers') {
  if (p.product || p.slug) {
    return await queryProductOffers(p.product || p.slug, p);
  }
  const qs = new URLSearchParams();
  if (p.q) qs.set('q', String(p.q));
  if (p.platform) qs.set('platform', String(p.platform));
  if (p.type) qs.set('type', String(p.type));
  const stock = p.stock || 'available';
  qs.set('stock', stock);
  if (p.sort && VALID_OFFER_SORTS.has(String(p.sort))) qs.set('sort', String(p.sort));
  const minVal = parseNumOpt(p.min ?? p.minPrice);
  const maxVal = parseNumOpt(p.max ?? p.maxPrice);
  if (minVal != null) qs.set('min', String(minVal));
  if (maxVal != null) qs.set('max', String(maxVal));
  const reqLim = Math.max(1, Math.min(30, Number(p.limit) || 20));
  const reqOff = Math.max(0, Math.min(300, Number(p.offset) || 0));
  const excludeTokens = p.exclude ? norm(p.exclude).split(/\s+/).filter(Boolean) : [];
  const reqTags = parseTagList(p.tags ?? p.tag);
  const fetchLim = (excludeTokens.length || reqTags.length) ? 30 : reqLim;
  qs.set('limit', String(fetchLim));
  qs.set('offset', String(reqOff));
  const r = await fetchSite(`/api/offers?${qs.toString()}`);
  const data = r.json || {};
  let rows = Array.isArray(data.rows) ? data.rows : [];
  if (excludeTokens.length) {
    rows = rows.filter(({ offer: o }) => !excludeTokens.some(tk => norm(o.sourceTitle).includes(tk)));
  }
  if (reqTags.length) {
    rows = rows.filter(({ offer: o }) => reqTags.every(tg => offerMatchesClientTag(o, tg)));
  }
  rows = rows.slice(0, reqLim);
  return {
    total: data.total || 0,
    generatedAt: data.generatedAt,
    limit: reqLim,
    offset: reqOff,
    hasMore: (reqOff + fetchLim) < (data.total || 0) && (reqOff + fetchLim) <= 300,
    count: rows.length,
    rows: rows.map(({ offer: o, product: pr }) => ({
      id: o.id,
      title: o.sourceTitle,
      price: o.price,
      currency: o.currency,
      status: o.status,
      effectiveStatus: o.effectiveStatus,
      freshnessStatus: o.freshnessStatus || null,
      inStock: isTrulyAvailable(o),
      stockCount: o.stockCount,
      minOrderQuantity: o.minOrderQuantity,
      bulkPricingTiers: o.bulkPricingTiers,
      store: o.sourceStoreName || o.sourceName,
      filterTags: o.filterTags || [],
      url: o.url,
      shopUrl: o.shopUrl,
      lastSeenAt: o.lastSeenAt,
      product: pr ? { slug: pr.slug, name: pr.displayName, platform: pr.platform, productType: pr.productType } : null,
    })),
  };
}

// 7. 卡网商家排行榜（严守 limit<=30, offset<=1500；补全全部服务端筛选参数）
if (act === 'merchants') {
  const qs = new URLSearchParams();
  if (p.q) qs.set('q', String(p.q));
  if (p.platform) qs.set('platform', String(p.platform));
  if (p.type) qs.set('type', String(p.type));
  if (p.stock) qs.set('stock', String(p.stock));
  if (p.sort && VALID_OFFER_SORTS.has(String(p.sort))) qs.set('sort', String(p.sort));
  const minVal = parseNumOpt(p.min ?? p.minPrice);
  const maxVal = parseNumOpt(p.max ?? p.maxPrice);
  if (minVal != null) qs.set('min', String(minVal));
  if (maxVal != null) qs.set('max', String(maxVal));
  if (p.signal && p.signal !== 'all') qs.set('signal', String(p.signal));
  if (p.collector && p.collector !== 'all') qs.set('collector', String(p.collector));
  const lim = Math.max(1, Math.min(30, Number(p.limit) || 20));
  const off = Math.max(0, Math.min(1500, Number(p.offset) || 0));
