  qs.set('offset', String(off));
  const r = await fetchSite(`/api/merchants?${qs.toString()}`);
  const data = r.json || {};
  return {
    total: data.total || 0,
    generatedAt: data.generatedAt,
    limit: lim,
    offset: off,
    rows: (data.rows || []).map(m => ({
