      lowestHitCount: m.lowestHitCount,
      top5HitCount: m.top5HitCount,
      warrantyLowestHitCount: m.warrantyLowestHitCount,
      compositeRankScore: m.compositeRankScore,
      healthStatus: m.healthStatus,
      hasPlatformAftersales: m.hasPlatformAftersalesMechanism,
      riskFeedbackCount: m.riskFeedbackCount,
      includedAt: m.includedAt,
      latestSeenAt: m.latestSeenAt,
    })),
  };
}

// 8. 官方 API 定价 / Token Plan / Coding Plan
if (act === 'api_plans') {
  const r = await fetchSite('/official-api');
  const rsc = getRscJoined(r.text);
  const providers = extractRscKey(rsc, 'providers') || [];
  const plans = extractRscKey(rsc, 'plans') || [];
  const models = extractRscKey(rsc, 'models') || [];
  const offers = extractRscKey(rsc, 'offers') || [];
  const view = norm(p.view || 'plans');
  const q = p.q || '';
  const fam = norm(p.family);
  const pid = norm(p.providerId);
  const lim = Math.max(1, Math.min(120, Number(p.limit) || 30));

  const provMap = Object.fromEntries(providers.map(x => [x.id, x]));
  const offersByModel = {};
  for (const o of offers) {
    if (!offersByModel[o.modelId]) offersByModel[o.modelId] = [];
    offersByModel[o.modelId].push({
      providerId: o.providerId,
      providerName: provMap[o.providerId]?.name || o.providerId,
      billingMode: o.billingMode,
      routeModelId: o.routeModelId,
      inputPrice: o.inputPrice,
      outputPrice: o.outputPrice,
      cacheReadPrice: o.cacheReadPrice,
      cacheWritePrice: o.cacheWritePrice,
      freeOrPlan: o.freeOrPlan,
      limitSummary: o.limitSummary,
      limitations: o.limitations,
      pricingUrl: o.pricingUrl,
    });
  }

  const res = { source: `${ORIGIN}/official-api`, counts: { providers: providers.length, plans: plans.length, models: models.length, offers: offers.length } };
  if (view === 'plans' || view === 'all') {
    const fl = plans.filter(x => (!pid || norm(x.providerId) === pid) && matchQ(q, x.name, x.providerName, x.priceLabel, x.quotaSummary, x.limitSummary, x.modelIds, x.suitableTools, x.compatibility));
    res.plans = fl.slice(0, lim).map(x => ({
      id: x.id,
      name: x.name,
      providerId: x.providerId,
      providerName: x.providerName,
      type: x.type,
      priceLabel: x.priceLabel,
      priceUsdMonthly: x.priceUsdMonthly,
      priceCnyMonthly: x.priceCnyMonthly,
      quotaSummary: x.quotaSummary,
      resetSummary: x.resetSummary,
      limitSummary: x.limitSummary,
      limitations: x.limitations,
      modelIds: x.modelIds,
      suitableTools: x.suitableTools,
      compatibility: x.compatibility,
      url: x.url,
      updatedAt: x.updatedAt,
    }));
  }
  if (view === 'models' || view === 'all') {
    const fm = models.filter(m => {
      if (fam && norm(m.family) !== fam && !norm(m.family).includes(fam)) return false;
      const mo = offersByModel[m.id] || [];
      if (pid && !mo.some(o => norm(o.providerId) === pid)) return false;
      return matchQ(q, m.displayName, m.id, m.modelId, m.family, m.description, m.capabilities, mo.map(o => o.providerName).join(' '));
    });
    res.models = fm.slice(0, lim).map(m => ({
      id: m.id,
      name: m.displayName,
      family: m.family,
      contextWindow: m.contextWindow,
      capabilities: m.capabilities,
      suitableTools: m.suitableTools,
      description: m.description,
      sourceUrl: m.sourceUrl,
      offers: offersByModel[m.id] || [],
    }));
  }
  if (view === 'providers' || view === 'all') {
    const fp = providers.filter(x => (!pid || norm(x.id) === pid) && matchQ(q, x.name, x.id, x.billingMode, x.description, x.limitSummary));
    res.providers = fp.slice(0, lim).map(x => ({
      id: x.id, name: x.name, type: x.type, billingMode: x.billingMode,
      url: x.url, pricingUrl: x.pricingUrl, description: x.description,
      limitSummary: x.limitSummary, limitations: x.limitations, updatedAt: x.updatedAt,
    }));
  }
  return res;
}

// 9. API 中转站排行 / 跨站模型比价 / 单站详情（单站优先走官方 JSON API /api/api-transit-stations/{slug}/detail）
if (act === 'transit') {
  const mode = norm(p.mode || (p.slug ? 'station' : 'ranking'));
  const lim = Math.max(1, Math.min(80, Number(p.limit) || 20));
  if (mode === 'station') {
    const slug = String(p.slug || '').trim().replace(/^\/+api-transit\//, '');
    if (!slug) throw new Error('请提供中转站 slug，例如 relaycore-cn、tokenshop-homes');
    let st = null;
    let sourceApi = 'json';
    try {
      const jr = await fetchSite(`/api/api-transit-stations/${encodeURIComponent(slug)}/detail`);
      st = jr.json?.station || null;
    } catch {}
    if (!st) {
      sourceApi = 'rsc';
      const r = await fetchSite(`/api-transit/${encodeURIComponent(slug)}`);
      st = extractRscKey(getRscJoined(r.text), 'station');
    }
    if (!st) throw new Error(`未找到中转站详情: ${slug}`);
    let prices = Array.isArray(st.prices) ? st.prices : [];
    if (p.q) prices = prices.filter(x => matchQ(p.q, x.standardModel, x.family, x.groupName, x.accountPool, x.billingMode));
    return {
      sourceApi,
      slug: st.slug,
      name: st.name,
      url: `${ORIGIN}/api-transit/${st.slug}`,
      websiteUrl: st.websiteUrl,
      apiBaseUrl: st.apiBaseUrl,
      stationSystem: st.stationSystem,
      operatorType: st.operatorType,
      invoiceSupport: st.invoiceSupport,
      summary: st.summary,
      channelTypes: st.channelTypes,
      accountPools: st.accountPools,
      paymentMethods: st.paymentMethods,
      minimumTopUp: st.minimumTopUp,
      balanceExpiry: st.balanceExpiry,
      refundPolicy: st.refundPolicy,
      riskLabels: st.riskLabels,
      usageAdvice: st.usageAdvice,
      availability: st.availability,
      commercialOffers: st.commercialOffers,
      lastUpdatedAt: st.lastUpdatedAt,
      priceCount: (st.prices || []).length,
      matchedPrices: prices.length,
      prices: prices.slice(0, lim).map(x => ({
        model: x.standardModel,
        family: x.family,
        groupName: x.groupName,
        accountPool: x.accountPool,
        billingMode: x.billingMode,
        rechargeRatio: x.rechargeRatio,
        multiplier: x.modelMultiplier,
        inputPrice: x.inputPrice,
        outputPrice: x.outputPrice,
        cacheReadPrice: x.cacheReadPrice,
        fixedPrice: x.fixedPrice,
        currency: x.currency,
        sevenDayRate: x.availability?.sevenDayRate ?? null,
        requestCount: x.availability?.requestCount ?? null,
        avgLatency7dMs: x.availability?.avgLatency7dMs ?? null,
        cacheHitRate: x.cacheUsage?.hitRate ?? null,
        lastVerifiedAt: x.lastVerifiedAt,
      })),
    };
  }
  if (mode === 'models') {
    const r = await fetchSite('/api-transit/models');
    const rsc = getRscJoined(r.text);
    const stations = extractRscKey(rsc, 'stations') || [];
    const summaries = extractRscKey(rsc, 'summaries') || [];
    const fam = norm(p.family);
    const q = p.q || '';
    const maxRate = p.maxRate != null && p.maxRate !== '' ? Number(p.maxRate) : null;
    const minAvail = p.minAvail != null && p.minAvail !== '' ? Number(p.minAvail) : null;
    const filtered = summaries.filter(s => {
      if (fam && norm(s.family) !== fam && norm(s.familyLabel) !== fam) return false;
      if (maxRate != null && (s.bestCombinedRate == null || s.bestCombinedRate > maxRate)) return false;
      if (minAvail != null && (s.averageAvailability == null || s.averageAvailability < minAvail)) return false;
      return matchQ(q, s.standardModel, s.family, s.familyLabel);
    });
    return {
      source: `${ORIGIN}/api-transit/models`,
      stationCount: stations.length,
      matchedModels: filtered.length,
      models: filtered.slice(0, lim).map(s => {
        const topEntries = (s.entries || [])
          .filter(e => Array.isArray(e) && e[4] != null && (minAvail == null || (e[5] ?? 0) >= minAvail))
          .sort((a, b) => (a[4] ?? 999) - (b[4] ?? 999))
          .slice(0, 5)
          .map(e => {
            const st = stations[e[0]] || [];
            return {
              station: st[0] || `#${e[0]}`,
              riskLabels: st[1] || [],
              usageAdvice: st[2] || null,
              channelTypes: e[1],
              accountPool: e[2],
              fixedPrice: e[3],
              combinedRate: e[4],
              availability: e[5],
              sampleCount: e[6],
            };
          });
        return {
          model: s.standardModel,
          family: s.familyLabel || s.family,
          stationCount: s.stationCount,
          bestCombinedRate: s.bestCombinedRate,
          worstCombinedRate: s.worstCombinedRate,
          bestFixedPrice: s.bestFixedPrice,
          averageAvailability: s.averageAvailability != null ? Math.round(s.averageAvailability * 10000) / 10000 : null,
          sampleCount: s.sampleCount,
          topStations: topEntries,
        };
      }),
    };
  }
  const r = await fetchSite('/api-transit');
  const tableMatch = r.text.match(/<table[\s\S]*?<\/table>/i);
  const tbody = tableMatch ? (tableMatch[0].match(/<tbody[^>]*>([\s\S]*?)<\/tbody>/i)?.[1] || '') : '';
  const trs = [...tbody.matchAll(/<tr[^>]*>([\s\S]*?)<\/tr>/gi)];
  const rows = trs.map(m => {
    const slug = m[1].match(/href="\/api-transit\/([^"]+)"/)?.[1] || '';
    const tds = [...m[1].matchAll(/<td[^>]*>([\s\S]*?)<\/td>/gi)].map(x => stripTags(x[1]));
    return {
      rank: Number(tds[0]) || tds[0],
      slug,
      name: tds[1],
      chatgptRate: tds[2],
      claudeRate: tds[3],
      geminiRate: tds[4],
      availability7d: tds[5],
      updatedAt: tds[6],
      url: slug ? `${ORIGIN}/api-transit/${slug}` : null,
    };
  }).filter(x => x.slug && matchQ(p.q, x.name, x.slug, x.chatgptRate, x.claudeRate, x.geminiRate));
  return { source: `${ORIGIN}/api-transit`, total: rows.length, stations: rows.slice(0, lim) };
}

// 10. 订阅与避坑指南（正文优先走官方原生 Markdown /guides/md/{slug}）
if (act === 'guides') {
  const slug = String(p.slug || '').trim().replace(/^\/+guides\//, '');
  if (!slug) {
    const r = await fetchSite('/guides');
    const seen = new Map();
    for (const m of r.text.matchAll(/<a[^>]*href="(\/guides\/[a-z0-9-]+)"[^>]*>([\s\S]*?)<\/a>/gi)) {
      const s = m[1].replace('/guides/', '');
      const text = stripTags(m[2]);
      if (!text) continue;
      const prev = seen.get(s);
      if (!prev || text.length > prev.text.length) seen.set(s, { slug: s, text, url: ORIGIN + m[1], markdownUrl: `${ORIGIN}/guides/md/${s}` });
    }
    return { source: `${ORIGIN}/guides`, count: seen.size, guides: [...seen.values()] };
  }
  const maxChars = Number(p.maxChars) || 12000;
  try {
    const mr = await fetchSite(`/guides/md/${encodeURIComponent(slug)}`);
    const md = String(mr.text || '').trim();
    if (md.length > 40) {
      return {
        slug,
        format: 'markdown',
        url: `${ORIGIN}/guides/${slug}`,
        markdownUrl: `${ORIGIN}/guides/md/${slug}`,
        length: md.length,
        content: md.slice(0, maxChars),
      };
    }
  } catch {}
  const r = await fetchSite(`/guides/${encodeURIComponent(slug)}`);
  const mainHtml = r.text.match(/<article[\s\S]*?<\/article>/i)?.[0] || r.text.match(/<main[\s\S]*?<\/main>/i)?.[0] || '';
  if (!mainHtml) throw new Error(`未找到指南内容: ${slug}`);
  const cleaned = mainHtml
    .replace(/<(script|style|svg|noscript|nav|aside)[\s\S]*?<\/\1>/gi, '')
    .replace(/<\/(h1|h2|h3|h4|p|li|tr|div|section)>/gi, '\n')
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<[^>]+>/g, '');
  const text = decodeHtml(cleaned).replace(/[ \t]+/g, ' ').replace(/\n[ \t]+/g, '\n').replace(/\n{3,}/g, '\n\n').trim();
  return {
    slug,
    format: 'html_text',
    url: `${ORIGIN}/guides/${slug}`,
    length: text.length,
    content: text.slice(0, maxChars),
  };
}

throw new Error('未知 action: ' + act + '，支持: official_plans, official_regions, products, product_detail, radar, offers, merchants, api_plans, transit, guides');
